"""Refresh the copilot's knowledge: hand-written policy docs plus documents generated by this run.

Each pipeline run writes a model card and pattern briefs from its own results, so the copilot
can answer "what does the model use?" or "what is the emerging pattern?" with the numbers of
the current run, cited like any other source.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from fraudops.config import Settings
from fraudops.features import EXCLUDED_FEATURES
from fraudops.rag.llm import LLMUnavailable, LocalLLM, llm_disabled
from fraudops.rag.retrieval import KnowledgeBase

FEATURE_GROUPS = {
    "What happened": "loss type, province, amounts (total, injury reserve, repair), repair-to-value ratio, total loss, "
                     "hour of loss, occupants and injured, soft-tissue only, police report, witnesses, towing distance, "
                     "storage days and fees",
    "Who is claiming": "policy age at the time of loss, days between loss and report, prior claims in three years, "
                       "whether the claimant is represented",
    "Network": "how often the phone number and address appeared on claims in the past year, body shop, clinic and tow "
               "operator volumes, the body shop's average repair-to-value ratio, the tow operator's average storage "
               "days, and repeated pairings of the same representative and clinic",
    "Narrative": "a text model's probability that the adjuster notes resemble confirmed fraud files (place names removed)",
}
FEATURE_LABELS = {
    "narrative_risk": "Narrative resembles confirmed fraud notes", "shop_avg_repair_ratio_180d": "Body shop's average repair-to-value ratio",
    "repair_to_value": "Repair estimate vs vehicle value", "log_repair_estimate": "Repair estimate", "loss_type": "Loss type",
    "shop_prior_claims_90d": "Body shop claim volume", "log_total_claimed": "Total claimed", "policy_tenure_days": "Policy age",
    "n_injured": "Number injured", "vehicle_value": "Vehicle value", "report_delay_days": "Days to report",
    "prior_claims_3y": "Prior claims", "vehicle_age": "Vehicle age", "loss_hour": "Hour of loss", "injured_share": "Share of occupants injured",
    "rep_clinic_prior_claims_365d": "Representative + clinic pairings", "phone_prior_claims_365d": "Phone number reuse",
    "address_prior_claims_365d": "Address reuse", "clinic_prior_claims_90d": "Clinic claim volume", "province": "Province",
    "soft_tissue_only": "Soft-tissue only", "represented": "Represented", "log_injury_reserve": "Injury reserve",
    "tow_fee": "Towing and storage fees", "storage_days": "Storage days", "tow_distance_km": "Tow distance",
}


def _money(value: float) -> str:
    return f"${value:,.0f}"


def _read(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def model_card(metrics: dict[str, Any], policy: dict[str, Any]) -> str:
    champion = metrics["champion"]
    test = metrics["candidates"][champion["candidate"]]["test"]
    rules = metrics["candidates"]["rules"]["test"]
    random = metrics["random_test"]
    data = metrics["data"]
    lines = [
        f"# Model Card: {champion['model_name']} version {champion['version']}",
        "",
        "Generated by the pipeline from the run's own results. All data is synthetic.",
        "",
        "## Intended use",
        "",
        f"Ranks newly reported auto claims so the SIU can choose which {policy['capacity']} files to open each month, and "
        f"marks low-risk claims (fraud probability below {policy['fast_track_below']}) for fast-track payment. It is not "
        "used for denying claims, pricing, underwriting or deciding coverage, and a score is never evidence of fraud.",
        "",
        "## Training data",
        "",
        f"Training months {data['train']['months'][0]} to {data['train']['months'][1]} ({data['train']['rows']:,} claims, "
        f"fraud rate {data['train']['fraud_rate']:.1%}). Validation months {data['valid']['months'][0]} to "
        f"{data['valid']['months'][1]} were used for early stopping, calibration and choosing between candidates. Test months "
        f"{data['test']['months'][0]} to {data['test']['months'][1]} ({data['test']['rows']:,} claims) were used once, for the "
        "results below. The split is by time, never random, because the model has to predict next month.",
        "",
        "## Features the model uses",
        "",
        *[f"- {group}: {text}." for group, text in FEATURE_GROUPS.items()],
        "",
        "## Features deliberately excluded",
        "",
        *[f"- {name}: {reason}." for name, reason in EXCLUDED_FEATURES.items()],
        "",
        "The model does not use the claimant's age, sex, ethnicity, language or any other protected ground.",
        "",
        "## Performance on the held-out test months",
        "",
        f"The champion is a {champion['candidate']} model. On the test months it reached ROC-AUC {test['roc_auc']:.3f} and "
        f"PR-AUC {test['pr_auc']:.3f}, against {rules['roc_auc']:.3f} and {rules['pr_auc']:.3f} for the red-flag scorecard "
        "used today.",
        "",
        f"With the SIU's real capacity of {policy['capacity']} files a month, the model's queue caught {test['frauds_caught']:.1f} "
        f"frauds a month ({test['hit_rate']:.0%} of opened files) and {test['dollar_recall']:.0%} of fraudulent dollars, for "
        f"a net saving of {_money(test['net_savings'])} a month. The scorecard's queue caught {rules['frauds_caught']:.1f} "
        f"frauds ({rules['hit_rate']:.0%} of files) for {_money(rules['net_savings'])} a month, and picking files at random "
        f"would save {_money(random['net_savings'])}. The model also opened {test['honest_investigated']:.1f} files a month "
        f"on honest customers, against {rules['honest_investigated']:.1f} for the scorecard.",
        "",
        "## Decision rule",
        "",
        f"Claims are ranked by expected net saving: probability x claimed amount x recovery rate ({policy['recovery_rate']:.0%}) "
        f"minus the investigation cost ({_money(policy['investigation_cost'])}). Claims with a negative expected saving are "
        f"not opened. Claims with a probability of {policy['review_above']} or more that do not make the queue go to an "
        "adjuster's red-flag review.",
        "",
        "## What drives the score",
        "",
        "Average absolute contribution to the log-odds on the test months (higher means more influential):",
        "",
        *[f"- {FEATURE_LABELS.get(name, name)}: {value:.3f}" for name, value in list(metrics["importance"].items())[:10]],
        "",
        "## Known limitations",
        "",
        "- The model only recognises fraud that looks like fraud it was trained on. A new scheme is invisible to it until "
        "investigators label examples; the pattern monitor exists to catch exactly that gap.",
        "- In a real deployment, labels exist only for claims that were investigated, so the training data over-represents "
        "what investigators already suspected.",
        "- Calibration was fitted on three months with few confirmed frauds; probabilities above 0.5 are less precise than "
        "the ranking.",
        "- Soft fraud (padding an honest loss) is common and mostly undetectable from these features.",
        "",
        "## Version and lineage",
        "",
        f"Registered model {champion['model_name']} version {champion['version']}, MLflow run {champion['mlflow_run_id']}, "
        f"trained {champion['trained_at']}. Promotion decision for this run: {metrics['decision']}.",
    ]
    return "\n".join(lines) + "\n"


def pattern_briefs(segments: dict[str, Any], rings: dict[str, Any], drift: dict[str, Any], latest: dict[str, Any],
                   titles: dict[str, dict[str, str]]) -> str:
    month = segments["current_month"]
    lines = [f"# Pattern Briefs for {month}", "",
             "Generated by the pipeline from this month's segments, emerging patterns, rings and drift checks. "
             "All data is synthetic.", ""]
    for pattern in segments["emerging"]:
        providers = ", ".join(f"{kind.replace('_', ' ')} {info['value']} on {info['share']:.0%} of them"
                              for kind, info in pattern["shared_providers"].items())
        distinctive = "; ".join(f"{_label(item['feature'])} average {_fmt(item['feature'], item['current_mean'])} "
                                f"against {_fmt(item['feature'], item['reference_mean'])} last year"
                                for item in pattern["distinctive"][:3])
        trend = pattern.get("trend")
        title = titles.get(pattern["id"], {}).get("title", "")
        lines += [
            f"## Emerging pattern {pattern['id']}: {title}",
            "",
            f"{pattern['claims']} claims this month, {_money(pattern['total_claimed'])} claimed, belong to a kind of claim that "
            f"is far more common than in the previous 12 months. Shared providers: {providers or 'none dominant'}. What sets "
            f"them apart: {distinctive}. Words over-represented in their notes: {', '.join(pattern['top_terms'])}. Cities: "
            f"{', '.join(pattern['cities'])}.",
            "",
            f"The triage model gives them an average fraud probability of {pattern['avg_probability']:.1%} and put "
            f"{_plural(pattern['in_queue'], 'of them', 'of them')} in the SIU queue: it has not seen this kind of claim "
            "before. "
            + (f"Claims involving {trend['provider']} by month: "
               + ", ".join(f"{m}: {c}" for m, c in zip(trend["months"][-4:], trend["claims"][-4:], strict=True)) + ". "
               if trend else "")
            + "Recommended action: refer the group to the SIU lead as one pattern, and label the investigated claims so the "
              "next model version can learn it.",
            "",
        ]
    for ring in rings["rings"][:3]:
        providers = ", ".join(f"{kind.replace('_', ' ')} {info['value']} ({info['share']:.0%})" for kind, info in ring["providers"].items())
        title = titles.get(ring["id"], {}).get("title", "")
        lines += [
            f"## Ring {ring['id']}: {title}",
            "",
            f"{ring['claims']} claims linked through {_plural(ring['shared_phones'], 'shared phone number', 'shared phone numbers')} "
            f"and {_plural(ring['shared_addresses'], 'shared address', 'shared addresses')}, active in {ring['months_active']} "
            f"months from {ring['first_month']} to {ring['last_month']}, {_money(ring['total_claimed'])} claimed in total, "
            f"{ring['avg_injured']:.1f} injured people per claim on average. Main cities: {', '.join(ring['cities'])}. "
            f"Recurring providers: {providers or 'none dominant'}. "
            f"{_plural(ring['claims_current_month'], 'claim was', 'claims were')} reported this month. Average model "
            f"probability: {ring['avg_probability']:.0%}.",
            "",
        ]
    risky = sorted(segments["segments"], key=lambda s: -s["confirmed_fraud_rate"])
    lines += ["## Claim segments", "",
              f"Claims from {segments['reference_months'][0]} to {segments['reference_months'][1]} fall into "
              f"{len(risky)} segments. From most to least fraud-prone:", ""]
    for seg in risky:
        lines.append(f"- Segment {seg['id']}, {seg['name']}: {seg['claims_reference']:,} claims last year, "
                     f"{seg['confirmed_fraud_rate']:.1%} confirmed fraud, average claim {_money(seg['avg_claimed'])}, "
                     f"{seg['share_current']:.1%} of this month's claims.")
    alerts = [row for row in drift["features"] if row["status"] == "alert"]
    lines += ["", "## Drift alerts this month", ""]
    if alerts:
        for row in alerts:
            lines.append(f"- {row['feature'].replace('_', ' ')}: PSI {row['psi']}, {row['tail_claims']} claims above last "
                         f"year's 99th percentile ({row['tail_ratio']}x the usual rate).")
    else:
        lines.append("- No feature crossed an alert threshold.")
    lines.append(f"- Model score: PSI {drift['score']['psi']} between the test months and this month.")
    bands = latest["bands"]
    lines += ["", "## This month's queue", "",
              f"{latest['claims']} claims were scored for {month}: {bands.get('Investigate', 0)} in the SIU queue, "
              f"{bands.get('Review', 0)} for adjuster red-flag review, {bands.get('Standard', 0)} standard and "
              f"{bands.get('Fast-track', 0)} fast-tracked. The queue's expected net saving is {_money(latest['queue_value'])}."]
    return "\n".join(line for line in lines) + "\n"


UNITS = {"tow_fee": "${:,.0f}", "storage_days": "{:,.0f} days", "tow_distance_km": "{:,.0f} km",
         "log_total_claimed": None, "log_injury_reserve": None, "log_repair_estimate": None}
BANNED = ("fraud", "scam", "criminal", "illegal", "fake", "staged")


def _fmt(feature: str, value: float) -> str:
    if feature == "storage_days":
        return _plural(round(value), "day", "days")
    template = UNITS.get(feature, "{:,.1f}")
    return f"{value:,.1f}" if template is None else template.format(value)


def _label(feature: str) -> str:
    return FEATURE_LABELS.get(feature, feature.replace("_", " ")).lower()


def _plural(n: int, one: str, many: str) -> str:
    return f"{n} {one if n == 1 else many}"


def pattern_title(pattern: dict[str, Any]) -> str:
    feature = _label(pattern["distinctive"][0]["feature"]) if pattern["distinctive"] else "claim mix"
    lead = next(iter(pattern["shared_providers"].values()), None)
    return f"Unusual {feature}" + (f" around {lead['value']}" if lead else "")


def ring_title(ring: dict[str, Any]) -> str:
    city = next(iter(ring["cities"]), "")
    people = [ring["providers"][kind]["value"] for kind in ("clinic", "representative") if kind in ring["providers"]]
    injured = "multi-injury claims" if ring["avg_injured"] >= 2 else "claims"
    return f"{city} {injured}" + (f" around {' and '.join(people)}" if people else "")


def title_patterns(llm: LocalLLM | None, segments: dict[str, Any], rings: dict[str, Any]) -> dict[str, dict[str, str]]:
    """A short title per emerging pattern (local model, checked) and per ring (rule-based).

    A 3B local model names a new pattern well but drifts into accusation in longer prose, so it
    is only asked for a title, and a title that accuses, rambles or repeats is replaced by the
    rule-based one. Ring titles are rule-based: their facts (city, clinic, representative) are
    already the best title.
    """
    system = ("You name groups of insurance claims for investigators. Reply with only a title of 3 to 7 words that says "
              "what the claims have in common, such as 'Long tows to distant storage yards'. Never use the words fraud, "
              "fraudulent, scam, staged or criminal.")
    titles: dict[str, dict[str, str]] = {}
    for pattern in segments["emerging"]:
        title, source = pattern_title(pattern), "rule"
        if llm is not None:
            facts = {k: pattern[k] for k in ("claims", "shared_providers", "distinctive", "top_terms", "cities")}
            try:
                answer = llm.chat(system, json.dumps(facts), max_tokens=24, temperature=0.1).strip().strip('"\'.').strip()
                used = {item["title"].lower() for item in titles.values()}
                if 2 <= len(answer.split()) <= 8 and not any(w in answer.lower() for w in BANNED) and answer.lower() not in used:
                    title, source = answer, "llm"
            except LLMUnavailable:
                llm = None
        titles[pattern["id"]] = {"title": title, "source": source}
    for ring in rings["rings"][:3]:
        titles[ring["id"]] = {"title": ring_title(ring), "source": "rule"}
    return titles


def run(settings: Settings) -> dict[str, Any]:
    paths = settings.paths
    reports = paths.reports
    from fraudops.business import SiuPolicy

    policy = SiuPolicy.from_settings(settings).__dict__
    llm = None if llm_disabled() else LocalLLM()
    if llm is not None and not llm.status()["ready"]:
        llm = None
    segments, rings = _read(reports / "segments.json"), _read(reports / "rings.json")
    titles = title_patterns(llm, segments, rings)
    paths.kb_generated.mkdir(parents=True, exist_ok=True)
    (paths.kb_generated / "model-card.md").write_text(model_card(_read(reports / "metrics.json"), policy), encoding="utf-8")
    (paths.kb_generated / "pattern-briefs.md").write_text(
        pattern_briefs(segments, rings, _read(reports / "drift.json"), _read(reports / "latest_month.json"), titles),
        encoding="utf-8")
    documents = sorted(paths.knowledge.glob("*.md")) + sorted(paths.kb_generated.glob("*.md"))
    kb = KnowledgeBase.build(documents, llm)
    kb.save(paths.kb_index)
    (reports / "pattern_titles.json").write_text(json.dumps(titles, indent=2), encoding="utf-8")
    return {"documents": len(documents), "chunks": len(kb.chunks), "mode": "hybrid" if kb.has_vectors else "keyword",
            "titles": sum(1 for t in titles.values() if t["source"] == "llm")}
